#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')
CATALOG_PATH = ROOT / 'therapy_catalog.json'
BAG_SUPPLY_PATH = ROOT / 'bag_supply_cost.csv'
DELIVERY_PAYMENT_PATH = ROOT / 'delivery_payment.csv'
PATIENT_OVERRIDES_PATH = ROOT / 'patient_overrides.csv'
ANALYSIS_PATH = ROOT / 'infusion_batch_analysis.json'
SUMMARY_PATH = ROOT / 'infusion_batch_summary.md'

DAYS_7 = 7
DELIVERIES_7 = 52
DAYS_14 = 14
DELIVERIES_14 = 26
THRESHOLD_USD = 15000


def money(value):
    return round(float(value), 2)


def normalize_label(value):
    return str(value).strip().casefold()


def read_csv_rows(path):
    with path.open(newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))


def patient_count_column(fieldnames):
    preferred = ['active_patients', 'patient_count', 'patients', 'active_patient_count']
    for name in preferred:
        if name in fieldnames:
            return name
    for name in fieldnames:
        lowered = name.lower()
        if 'patient' in lowered and ('count' in lowered or 'active' in lowered):
            return name
    raise KeyError('No active patient count column found in patient_overrides.csv')


def model_financials(therapy, active_patients, bag_supply_cost, payment, days_per_delivery, deliveries_per_year):
    annual_drug_cost = (
        float(therapy['drug_cost_per_1000_mg_usd'])
        * active_patients
        * float(therapy['dose_mg_per_day'])
        * days_per_delivery
        * deliveries_per_year
        / 1000
    )
    annual_supply_cost = bag_supply_cost * active_patients * deliveries_per_year
    annual_revenue = payment * active_patients * deliveries_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
    return {
        'days_per_delivery': days_per_delivery,
        'deliveries_per_year': deliveries_per_year,
        'annual_drug_cost': money(annual_drug_cost),
        'annual_supply_cost': money(annual_supply_cost),
        'annual_revenue': money(annual_revenue),
        'annual_margin': money(annual_margin),
    }


def main():
    with CATALOG_PATH.open(encoding='utf-8') as f:
        catalog = json.load(f)

    in_scope = []
    for service_line in catalog.get('service_lines', []):
        for therapy in service_line.get('therapies', []):
            if therapy.get('include_in_review') is True:
                copied = dict(therapy)
                copied['service_line'] = service_line.get('service_line')
                in_scope.append(copied)

    therapies_by_code = {therapy['therapy_code']: therapy for therapy in in_scope}

    bag_rows = read_csv_rows(BAG_SUPPLY_PATH)
    bag_cost_by_size = {
        int(row['bag_size_ml']): float(row['bag_supply_cost_usd'])
        for row in bag_rows
        if row.get('bag_size_ml') not in (None, '')
    }

    label_to_code = {}
    for therapy in in_scope:
        labels = [therapy['therapy_name'], *therapy.get('aliases', [])]
        for label in labels:
            label_to_code[normalize_label(label)] = therapy['therapy_code']

    payment_by_code = {}
    for row in read_csv_rows(DELIVERY_PAYMENT_PATH):
        code = label_to_code.get(normalize_label(row.get('therapy_label', '')))
        if code in therapies_by_code:
            payment_by_code[code] = float(row['payment_per_delivery_per_patient_usd'])

    patient_rows = read_csv_rows(PATIENT_OVERRIDES_PATH)
    count_col = patient_count_column(patient_rows[0].keys() if patient_rows else [])
    approved_by_code = {}
    for row in patient_rows:
        code = row.get('therapy_code')
        if code not in therapies_by_code or row.get('status') != 'approved':
            continue
        revision = int(row['revision'])
        current = approved_by_code.get(code)
        if current is None or revision > int(current['revision']):
            approved_by_code[code] = row

    therapy_results = []
    total_margin_7 = 0.0
    total_margin_14 = 0.0
    total_difference = 0.0

    for therapy in sorted(in_scope, key=lambda item: item['therapy_code']):
        code = therapy['therapy_code']
        if code not in approved_by_code:
            raise KeyError(f'Missing approved patient override for in-scope therapy {code}')
        if code not in payment_by_code:
            raise KeyError(f'Missing delivery payment for in-scope therapy {code}')

        bag_size = int(therapy['bag_size_ml'])
        if bag_size not in bag_cost_by_size:
            raise KeyError(f'Missing bag supply cost for bag_size_ml={bag_size}')

        active_patients = int(float(approved_by_code[code][count_col]))
        bag_supply_cost = bag_cost_by_size[bag_size]
        payment = payment_by_code[code]

        seven_day = model_financials(therapy, active_patients, bag_supply_cost, payment, DAYS_7, DELIVERIES_7)
        fourteen_day = model_financials(therapy, active_patients, bag_supply_cost, payment, DAYS_14, DELIVERIES_14)
        difference = money(fourteen_day['annual_margin'] - seven_day['annual_margin'])

        total_margin_7 += seven_day['annual_margin']
        total_margin_14 += fourteen_day['annual_margin']
        total_difference += difference

        therapy_results.append({
            'therapy_code': code,
            'therapy_name': therapy['therapy_name'],
            'active_patients': active_patients,
            'drug_cost_per_1000_mg_usd': money(therapy['drug_cost_per_1000_mg_usd']),
            'dose_mg_per_day': therapy['dose_mg_per_day'],
            'bag_size_ml': bag_size,
            'bag_supply_cost_usd': money(bag_supply_cost),
            'payment_per_delivery_per_patient_usd': money(payment),
            'seven_day_model': seven_day,
            'fourteen_day_model': fourteen_day,
            'annual_margin_difference_14_minus_7': difference,
        })

    total_margin_7 = money(total_margin_7)
    total_margin_14 = money(total_margin_14)
    total_difference = money(total_difference)
    absolute_difference = money(abs(total_difference))
    decision = 'move_to_14_day' if abs(total_difference) < THRESHOLD_USD else 'keep_7_day'

    analysis = {
        'assumptions': {
            'seven_day_model': {
                'days_per_delivery': DAYS_7,
                'deliveries_per_year': DELIVERIES_7,
            },
            'fourteen_day_model': {
                'days_per_delivery': DAYS_14,
                'deliveries_per_year': DELIVERIES_14,
            },
            'decision_threshold_usd': THRESHOLD_USD,
            'decision_rule': 'If abs(total_difference) < 15000, recommend move_to_14_day; otherwise, recommend keep_7_day.',
        },
        'therapies': therapy_results,
        'totals': {
            'total_annual_margin_7_day': total_margin_7,
            'total_annual_margin_14_day': total_margin_14,
            'total_difference': total_difference,
            'absolute_total_margin_difference': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f"Absolute total margin difference is ${absolute_difference:,.2f}, "
                f"which is {'below' if absolute_difference < THRESHOLD_USD else 'at or above'} "
                f"the ${THRESHOLD_USD:,.2f} threshold; recommend {decision}."
            ),
        },
    }

    with ANALYSIS_PATH.open('w', encoding='utf-8') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    with SUMMARY_PATH.open('w', encoding='utf-8') as f:
        f.write(f"Total 7-day margin: ${total_margin_7:,.2f}\n")
        f.write(f"Total 14-day margin: ${total_margin_14:,.2f}\n")
        f.write(f"Absolute difference: ${absolute_difference:,.2f}\n")
        f.write(f"Decision: {decision}\n")
        f.write(analysis['recommendation']['justification'] + '\n')


if __name__ == '__main__':
    main()

